/**
 * \file atma_patterns.h
 * \brief Generated sprite data: palette rows and 16x16 indexed cells.
 *
 * Generated by tools/mkpats.py from demo/atma.png; do not edit by hand.
 * Rerun the tool after changing the source image instead.
 */

#ifndef ATMA_PATTERNS_H
#define ATMA_PATTERNS_H

/** \brief Number of palette rows in atma_patterns_palette. */
#define ATMA_PATTERNS_PALETTE_N 7

/**
 * \brief Palette rows {index, r, g, b}: Next RGB333 values expanded to 8-bit
 *        components.
 *
 * Entry 0 is the transparent color; its RGB is a marker the generator picks
 * to keep the transparent slot visually distinct (nothing matches on it at
 * run time: transparency is by index).
 */
extern const unsigned char atma_patterns_palette[ATMA_PATTERNS_PALETTE_N][4];

/** \brief Number of 16x16 cells in atma_patterns_cells. */
#define ATMA_PATTERNS_CELLS 8
#define ATMA_PATTERNS_COLS 4 /**< Cells across. */
#define ATMA_PATTERNS_ROWS 2 /**< Cells down. */

/**
 * \brief The image as 8 cell(s) of 16x16 palette indexes.
 *
 * 4 column(s) x 2 row(s), row-major, padded with index 0 where the image
 * doesn't fill a cell.
 */
extern const unsigned char atma_patterns_cells[ATMA_PATTERNS_CELLS][16 * 16];

#endif
